// Categorize and validate expenses
const quarterData = $('Code - Calculate Quarter Range').first().json;
const expenseItems = $('Notion - Get Quarter Expenses').all() || [];
const revenueItems = $('Notion - Get Quarter Revenue').all() || [];

// IRS Category Mapping
const irsCategoryMap = {
  'Software/SaaS': 'Software',
  'Marketing & Advertising': 'Advertising',
  'Office Supplies': 'Office Expense',
  'Professional Services': 'Legal and Professional Services',
  'Meals & Entertainment': 'Meals',
  'Travel & Transportation': 'Travel',
  'Equipment & Hardware': 'Equipment',
  'Subscriptions & Memberships': 'Other Business Expenses',
  'Banking Fees': 'Bank Service Charges',
  'Taxes & Licenses': 'Taxes and Licenses',
  'Miscellaneous': 'Other Business Expenses',
  'Uncategorized': 'Other Business Expenses'
};

const validatedExpenses = [];
const flaggedExpenses = [];

expenseItems.forEach(item => {
  const expense = item.json;
  const notionCategory = expense.properties?.Categories?.relation?.[0]?.id || 'Uncategorized';
  const irsCategory = irsCategoryMap[notionCategory] || 'Other Business Expenses';
  const receiptStatus = expense.properties?.['Receipt Status']?.select?.name || 'Pending';
  const hasReceipt = receiptStatus === 'Validated' || receiptStatus === 'Added';

  const expenseData = {
    date: expense.properties?.Date?.date?.start || '',
    merchant: expense.properties?.Expense?.title?.[0]?.plain_text || 'Unknown',
    amount: expense.properties?.Amount?.number || 0,
    notionCategory,
    irsCategory,
    hasReceipt,
    receiptStatus,
    receiptUrl: expense.properties?.['Receipt URL']?.url || '',
    transactionId: expense.properties?.['Transaction ID']?.rich_text?.[0]?.plain_text || '',
    notes: expense.properties?.Notes?.rich_text?.[0]?.plain_text || '',
    notionUrl: expense.url
  };

  if (hasReceipt) {
    validatedExpenses.push(expenseData);
  } else {
    flaggedExpenses.push(expenseData);
  }
});

// Group by IRS category
const expensesByIRSCategory = {};
validatedExpenses.forEach(exp => {
  if (!expensesByIRSCategory[exp.irsCategory]) {
    expensesByIRSCategory[exp.irsCategory] = {
      total: 0,
      count: 0,
      items: []
    };
  }

  expensesByIRSCategory[exp.irsCategory].total += exp.amount;
  expensesByIRSCategory[exp.irsCategory].count++;
  expensesByIRSCategory[exp.irsCategory].items.push(exp);
});

// Calculate revenue
const grossRevenue = revenueItems.reduce((sum, item) => 
  sum + (item.json.properties?.Amount?.number || 0), 0
);

// Revenue by month
const revenueByMonth = {};
revenueItems.forEach(item => {
  const dateStr = item.json.properties?.Date?.date?.start;
  if (dateStr) {
    const month = dateStr.substring(0, 7);
    revenueByMonth[month] = (revenueByMonth[month] || 0) + (item.json.properties?.Amount?.number || 0);
  }
});

// Totals
const totalDeductible = validatedExpenses.reduce((sum, exp) => sum + exp.amount, 0);
const totalFlagged = flaggedExpenses.reduce((sum, exp) => sum + exp.amount, 0);
const taxableIncome = grossRevenue - totalDeductible;
const estimatedTax = Math.max(0, taxableIncome * 0.25); // ~25% combined estimate

return [{
  json: {
    ...quarterData,
    validatedExpenses,
    flaggedExpenses,
    expensesByIRSCategory,
    revenue: {
      grossRevenue,
      revenueByMonth,
      transactionCount: revenueItems.length
    },
    totals: {
      totalDeductible,
      totalFlagged,
      taxableIncome,
      estimatedTax
    }
  }
}];

// Generate CSV export
const data = $input.first().json;
const { validatedExpenses, quarter, year } = data;

// CSV header
let csv = 'Date,Merchant,Amount,IRS Category,Notion Category,Receipt,Transaction ID,Notes\n';

// Add each expense
validatedExpenses.forEach(exp => {
  csv += `"${exp.date}",`;
  csv += `"${exp.merchant.replace(/"/g, '""')}",`;
  csv += `${exp.amount.toFixed(2)},`;
  csv += `"${exp.irsCategory}",`;
  csv += `"${exp.notionCategory}",`;
  csv += `"${exp.receiptUrl}",`;
  csv += `"${exp.transactionId}",`;
  csv += `"${exp.notes.replace(/"/g, '""')}"\n`;
});

return [{
  json: {
    ...data,
    csvContent: csv,
    csvFilename: `${quarter}_${year}_Deductible_Expenses.csv`
  }
}];

// Format Slack summary
const data = $input.first().json;
const { quarter, year, revenue, totals, flaggedExpenses } = data;

let message = `:clipboard: *${quarter} ${year} Tax Prep Complete*\n\n`;
message += `*Gross Revenue:* $${revenue.grossRevenue.toFixed(2)}\n`;
message += `*Deductible Expenses:* $${totals.totalDeductible.toFixed(2)}\n`;
message += `*Estimated Tax:* $${totals.estimatedTax.toFixed(2)}\n\n`;

if (flaggedExpenses.length > 0) {
  message += `:warning: *Missing Receipts:* ${flaggedExpenses.length} items ($${totals.totalFlagged.toFixed(2)})\n\n`;
}

message += `*Documents ready:*\n`;
message += `• CSV Export\n`;
message += `• Detailed Email Summary\n\n`;
message += `Check your email for the full package.`;

return [{
  json: {
    ...data,
    slackMessage: message
  }
}];

